Q: what is the best practice to get the right compare of byte array? A: <p>Your <code>IsSec()</code> function is modifying the source arrays, so calling it on the same array over and over will not give you the results you are expecting. One call will reverse an array, and then the next call will un-reverse it, and so on as you move down your comparisons.</p>
<p>If you need to modify an array, <em>make a copy</em> of it first, and then modify the copy instead, eg:</p>
<pre class="lang-cs prettyprint-override"><code>private static bool IsSec(byte[] v, byte[] start, byte[] end)
{
    if (BitConverter.IsLittleEndian)
    {
        v = (byte[]) v.Clone();
        Array.Reverse(v);

        start = (byte[]) start.Clone();
        Array.Reverse(start);

        end = (byte[]) end.Clone();
        Array.Reverse(end);
    }

    int v1 = BitConverter.ToInt32(v, 0);
    int start1 = BitConverter.ToInt32(start, 0);
    int end1 = BitConverter.ToInt32(end, 0);

    return v1 &gt;= start1 &amp;&amp; v1 &lt;= end1;
}
</code></pre>
<p>However, in this situation, you don't need to deal with <code>byte[]</code> arrays at all. Just compare the numeric character values instead, eg:</p>
<pre class="lang-cs prettyprint-override"><code>private static string GetName(char ch)
{
    var d = &quot;&quot;;

    if (ch &gt;= '\x0000' &amp;&amp; ch &lt;= '\x00FF')
    {
        d = &quot;latin&quot;;
    }
    else if (ch &gt;= '\x0100' &amp;&amp; ch &lt;= '\x024F')
    {
        d = &quot;lating&quot;;
    }
    else if ((ch &gt;= '\x0250' &amp;&amp; ch &lt;= '\x02AF') ||
             (ch &gt;= '\x1D00' &amp;&amp; ch &lt;= '\x1D8F'))
    {
        d = &quot;s&quot;;
    }
    else if ((ch &gt;= '\x02B0' &amp;&amp; ch &lt;= '\x02FF') ||
             (ch &gt;= '\xA700' &amp;&amp; ch &lt;= '\xA71F'))
    {
        d = &quot;df&quot;;
    }
    else if ((ch &gt;= '\x0300' &amp;&amp; ch &lt;= '\x036F') ||
             (ch &gt;= '\x1DC0' &amp;&amp; ch &lt;= '\x1DFF'))
    {
        d = &quot;df&quot;;
    }
    else if (ch &gt;= '\x0370' &amp;&amp; ch &lt;= '\x03FF')
    {
        d = &quot;ssd&quot;;
    }
    ...

    return fontName;
}
</code></pre>
<p>Which can then be simplified by using a simple array of value, and a loop through that array, eg:</p>
<pre class="lang-cs prettyprint-override"><code>private struct NameInfo
{
    public char Start;
    public char End;
    public string Name;
}

private static NameInfo[] names = new NameInfo[]
{
    new NameInfo { Start = '\x0000', End = '\x00FF', Name = &quot;latin&quot; },
    new NameInfo { Start = '\x0100', End = '\x024F', Name = &quot;lating&quot; },
    new NameInfo { Start = '\x0250', End = '\x02AF', Name = &quot;s&quot; },
    new NameInfo { Start = '\x1D00', End = '\x1D8F', Name = &quot;s&quot; },
    new NameInfo { Start = '\x02B0', End = '\x02FF', Name = &quot;df&quot; },
    new NameInfo { Start = '\xA700', End = '\xA71F', Name = &quot;df&quot; },
    new NameInfo { Start = '\x0300', End = '\x036F', Name = &quot;df&quot; },
    new NameInfo { Start = '\x1DC0', End = '\x1DFF', Name = &quot;df&quot; },
    new NameInfo { Start = '\x0370', End = '\x03FF', Name = &quot;ssd&quot; },
    ...
};

private static string GetName(char ch)
{
    var d = &quot;&quot;;
    foreach (NameInfo entry in names)
    {
        if (ch &gt;= entry.Start &amp;&amp; ch &lt;= entry.End)
        {
            d = entry.Name;
            break;
        }
    }
    ...

    return fontName;
}
</code></pre>
